"""Produce a self-contained isolation page; never overwrite docs or state."""
import argparse
import json
from pathlib import Path
from fast_selection import safe_output

def build(payload,output):
    path=Path(output);safe_output(path.parent)
    root=Path(__file__).parent
    css=(root/'docs/status.css').read_text()
    js=(root/'fast_view.js').read_text()
    serialized=json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')
    html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>尾盤 ±3%｜快速結果隔離驗收</title><style>'''+css+'''
    .fast-panel{border:1px solid #273950;border-radius:14px;padding:18px;margin:18px 0;background:#111b2d}.fast-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.fast-metrics strong{display:block;font-size:24px;color:#e3ebfa}.fast-metrics span,.fast-evidence,small{color:#95a7c0;font-size:12px}td small{display:block;max-width:330px;white-space:normal;margin-top:5px}.fast-badge,.fast-missing{font-size:12px;color:#d7b971}.fast-panel p{line-height:1.7}button,select{color:#e3ebfa;background:#172840;border:1px solid #364960;border-radius:7px;padding:8px}.fast-controls{display:flex;gap:10px;margin-bottom:14px}.fast-controls select{min-width:0}th button{width:100%;border:0;background:transparent;padding:6px}th button:hover{background:#213957}th[aria-sort=ascending] .sort-arrow,th[aria-sort=descending] .sort-arrow{color:#66aeff}#fast-cards{display:none}#fast-empty{color:#b7c5da}.desktop-wrap{overflow:auto}#fast-note{color:#dfba70}@media(max-width:900px){.fast-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}#fast-cards{display:grid;gap:12px}.desktop-wrap{display:none}}
    </style><main><div class="eyebrow">隔離驗收 · 10/14 已保存證據離線重播</div><h1>尾盤 ±3% 快速結果</h1><p class="subtitle">目標 13:35～13:40；正式驗證目標尚未達成。這個頁面不會下單。</p><p>交易日 <strong id="trade-date"></strong></p><section class="fast-panel"><div class="fast-metrics"><div><span>研究候選</span><strong id="fast-count"></strong></div><div><span>完整驗證</span><strong id="fast-verified"></strong></div><div><span>全市場股票</span><strong id="fast-universe"></strong></div><div><span>尚未正式驗證</span><strong id="fast-pending"></strong></div></div><p id="fast-note" role="status"></p><p>已觀察 <span id="fast-observed"></span> 檔；僅觀察不等於通過驗證。</p></section><section class="fast-panel"><p>第一檔研究證據到齊：<strong id="fast-first"></strong><br>第一檔價格收斂與成交量到齊：<strong id="fast-complete"></strong><br>最後證據更新：<strong id="fast-last"></strong></p><p>以上是歷史證據的可用時間，並非當日真實上網發布時間。首次完整驗證與正式公開發布時間尚未取得。</p><p>最終官方稽核：<span id="fast-audit"></span></p></section><div class="list-heading"><h2>逐檔候選證據</h2><span>價格與數值顯示至小數點兩位</span></div><div class="fast-controls"><label for="fast-sort" class="sr-only">成交量排序</label><select id="fast-sort"><option value="">原始出現順序</option><option value="closing_auction_volume">最後一盤量</option><option value="intraday_total_volume">全日盤中量</option><option value="closing_volume_ratio_pct">收盤量占比</option></select><button id="fast-direction" type="button">由大到小 ↓</button></div><p id="fast-empty"></p><div class="desktop-wrap"><table><thead><tr><th>股票與時間</th><th>尾盤漲跌</th><th>13:25 前價</th><th>收盤價</th><th aria-sort="none"><button data-fast-sort="closing_auction_volume">最後一盤量<span class="sort-arrow">⇅</span></button></th><th aria-sort="none"><button data-fast-sort="intraday_total_volume">全日盤中量<span class="sort-arrow">⇅</span></button></th><th aria-sort="none"><button data-fast-sort="closing_volume_ratio_pct">收盤量占比<span class="sort-arrow">⇅</span></button></th><th>驗證狀態</th></tr></thead><tbody id="fast-rows"></tbody></table></div><div id="fast-cards"></div><footer>獨立來源證據未齊前，全部維持研究／待確認。正式網站與排程未更動。</footer></main><script>window.FastPayload='''+serialized+'''</script><script>'''+js+'''</script><script>window.FastController=FastView.create(document,FastPayload);if(location.protocol==='http:'&&['localhost','127.0.0.1'].includes(location.hostname)){setInterval(async()=>{try{const response=await fetch('fast-results.json',{cache:'no-store'});if(response.ok)FastController.render(await response.json());}catch{}},2000);}</script></html>'''
    path.write_text(html);return path

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('input',type=Path);p.add_argument('output',type=Path);a=p.parse_args()
    print(build(json.loads(a.input.read_text()),a.output))
